const text = $json.output;

const topPerformer =
  text.match(/TOP_PERFORMER:\s*(.*)/)?.[1]?.trim() || "";

const worstPerformer =
  text.match(/WORST_PERFORMER:\s*(.*)/)?.[1]?.trim() || "";

const recommendation =
  text.match(/RECOMMENDATION:\s*(.*)/)?.[1]?.trim() || "";

const alert =
  text.match(/ALERT:\s*(.*)/)?.[1]?.trim() || "";

const today = new Date().toISOString().split("T")[0];

return [
  {
    json: {
      memory_date: today,
      memory_type: "top_performer",
      content: topPerformer
    }
  },
  {
    json: {
      memory_date: today,
      memory_type: "worst_performer",
      content: worstPerformer
    }
  },
  {
    json: {
      memory_date: today,
      memory_type: "recommendation",
      content: recommendation
    }
  },
  {
    json: {
      memory_date: today,
      memory_type: "alert",
      content: alert
    }
  }
];

const items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      historicalMemory: null
    }
  }];
}

const historicalMemory = items
  .filter(item => item.json.memory_type)
  .map(item => ({
    type: item.json.memory_type,
    content: item.json.content,
    date: item.json.memory_date
  }));

return [{
  json: {
    historicalMemory: historicalMemory.length > 0
      ? historicalMemory
      : null
  }
}];

const items = $input.all();

const productMap = new Map();
const aggregated = {};

let productCounter = 1;

// Aggregate by SAG
for (const item of items) {

    const row = item.json;

    const sag = String(row.SAG || "Unknown Product");

    if (!aggregated[sag]) {
        aggregated[sag] = {
            impressions: 0,
            clicks: 0,
            spend: 0,
            campaigns: new Set()
        };
    }

    aggregated[sag].impressions += Number(row.impressions || 0);
    aggregated[sag].clicks += Number(row.clicks || 0);
    aggregated[sag].spend += Number(row.spend || 0);

    if (row.campaign_name) {
        aggregated[sag].campaigns.add(row.campaign_name);
    }
}

// Create anonymized output
const summarizedProducts = [];

for (const sag in aggregated) {

    if (!productMap.has(sag)) {
        productMap.set(
            sag,
            `Product_${productCounter++}`
        );
    }

    const productId = productMap.get(sag);

    const impressions = aggregated[sag].impressions;
    const clicks = aggregated[sag].clicks;
    const spend = aggregated[sag].spend;

    summarizedProducts.push({
        product: productId,
        impressions,
        clicks,
        spend,
        ctr:
            impressions > 0
                ? Number(((clicks / impressions) * 100).toFixed(2))
                : 0,
        campaign_count:
            aggregated[sag].campaigns.size
    });
}

// Reverse mapping
const productMapping = {};

for (const [original, masked] of productMap.entries()) {
    productMapping[masked] = original;
}

return [{
    json: {
        summarized_products: summarizedProducts,
        product_mapping: productMapping
    }
}];

// AI response
let report = $input.first().json.output;

// Pull mapping from anonymization node
const mapping =
$('anonimization code').first().json.product_mapping;

// Replace Product_X with original names
for (const [masked, original] of Object.entries(mapping)) {
    report = report.replaceAll(masked, original);
}

return [{
    json: {
        output: report
    }
}];

